  rib.position.y = -0.05;
  rib.castShadow = true;
  group.add(rib);
  for (const end of [-1, 1]) {
    const door = new THREE.Mesh(new THREE.BoxGeometry(0.18, height * 0.94, width * 0.94), material(0x3d3a35, { roughness: 1 }));
