  if (windows) {
    const band = new THREE.Mesh(new THREE.BoxGeometry(width * 0.8, height * 0.16, 0.14), material(PALETTE.glass, { roughness: 0.3, metalness: 0.2 }));
    band.position.set(0, height * 0.72, depth / 2 + 0.06);
